package main

import "fmt"

type Base struct{}

func (b Base) Name() string  { return "base" }
func (b Base) Hello() string { return "hello from " + b.Name() }

type Dog struct{ Base }

func (d Dog) Name() string { return "dog" }

func main() {
	d := Dog{}
	fmt.Println(d.Name())
	fmt.Println(d.Hello())
}

package main

import "fmt"

type Notifier interface{ Send(msg string) error }

type EmailSender struct{ From string }

func (e *EmailSender) Send(msg string) error {
	fmt.Println(e.From, "sends", msg)
	return nil
}

func notifyAll(ns []Notifier, msg string) {
	for _, n := range ns {
		n.Send(msg)
	}
}

func main() {
	notifyAll([]Notifier{EmailSender{From: "ops"}}, "deploy done")
}
